mapper.select:
SELECT v.activity_id, v.channel_id, COUNT(DISTINCT v.visitor_id) visits
FROM campaign_visit v JOIN campaign_activity a ON a.id = v.activity_id AND a.merchant_id = #{merchantId}
WHERE v.valid_flag = 1 AND v.visitor_id IS NOT NULL AND v.visitor_id != '' AND v.visitor_id NOT IN ('landing', 'anonymous')
  AND v.activity_id IN #{id}
GROUP BY v.activity_id, v.channel_id

SELECT id, name FROM campaign_activity WHERE merchant_id = #{merchantId}
AND LOWER(name) LIKE #{word} ESCAPE '!'
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
